subChunks.guidedPracticeModelAnswer:
Entities:
  Book {id, title, isbn, price}
  Genre {id, name}
  Author {id, name, bio}
  Customer {id, name, email}
  Order {id, customer_id→Customer, placed_at}
  OrderItem {id, order_id→Order, book_id→Book, quantity}
  book_genres (book_id→Book, genre_id→Genre)  -- junction table
  book_authors (book_id→Book, author_id→Author) -- junction table

Relationships:
  Customer 1→N Order (one customer, many orders)
  Order 1→N OrderItem (one order, many line items)
  Book M:N Genre (junction: book_genres)
  Book M:N Author (junction: book_authors)

CREATE TABLE books (
    id    INTEGER PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    isbn  VARCHAR(20) UNIQUE NOT NULL,
    price DECIMAL(10,2) NOT NULL
);
CREATE TABLE genres (
    id   INTEGER PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);
CREATE TABLE book_genres (
    book_id  INTEGER REFERENCES books(id),
    genre_id INTEGER REFERENCES genres(id),
    PRIMARY KEY (book_id, genre_id)
);
-- ... (similar for authors, customers, orders, order_items)

subChunks.modelAnswer:
Entities:
  Patient {id, name, dob, nhs_number UNIQUE}
  Doctor {id, name, specialisation, gmc_number UNIQUE}
  Appointment {id, patient_id→Patient, doctor_id→Doctor, scheduled_at TIMESTAMP, status VARCHAR}

Relationships:
  Patient M:N Doctor via Appointment (1 patient → many appointments; 1 doctor → many appointments)
  (Appointment is a rich junction table — it has its own attributes)

CREATE TABLE patients (
    id         INTEGER PRIMARY KEY,
    name       VARCHAR(200) NOT NULL,
    dob        DATE NOT NULL,
    nhs_number VARCHAR(20) UNIQUE NOT NULL
);
CREATE TABLE doctors (
    id             INTEGER PRIMARY KEY,
    name           VARCHAR(200) NOT NULL,
    specialisation VARCHAR(100),
    gmc_number     VARCHAR(20) UNIQUE NOT NULL
);
CREATE TABLE appointments (
    id           INTEGER PRIMARY KEY,
    patient_id   INTEGER NOT NULL REFERENCES patients(id),
    doctor_id    INTEGER NOT NULL REFERENCES doctors(id),
    scheduled_at TIMESTAMP NOT NULL,
    status       VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED'
);

Index to add:
  CREATE INDEX idx_appointments_doctor ON appointments(doctor_id);
  -- Reason: queries like 'all appointments for doctor X' will JOIN on doctor_id;
  -- without an index, a full table scan is needed for every lookup.
